"use client";
import { useEffect, useState } from "react";
import "./admin.css";
import {operationsFetch} from './api';
import {OperationsLogin} from './login';

type View="dashboard"|"users"|"benefits"|"products"|"orders"|"approvals"|"system"|"audit";
type User={id?:string;code:string;phone:string;name:string;profile:string;member:string;seed:number;status:string};
type Product={id:string;offeringId:string;serviceType:string;name:string;kind:"单次产品"|"服务包"|"会员计划";price:string;amountMinor:number;seedPrice:string;version:string;status:string;offeringStatus:"DRAFT"|"ACTIVE"|"INACTIVE"|"ARCHIVED";summary:string;validity:string;validityDays:number|null;delivery:string;contents:string[];entitlementSpec:Record<string,unknown>;promotion?:{enabled:boolean;minimumSeedBalance:number;reservedSeedQuantity:number;activityAmountMinor:number};draft?:Record<string,unknown>|null;pendingRequestId?:string|null};
const nav:[View,string,string][]=[["dashboard","工作台","台"],["users","用户中心","人"],["benefits","权益中心","益"],["products","商品中心","品"],["orders","交易中心","单"],["approvals","审核中心","审"],["audit","操作审计","记"],["system","系统管理","设"]];
const users:User[]=[];
const goods:Product[]=[];
