type UserIdentity={user_id?:string|null;phone_masked:string;nickname:string};
const statusCn:Record<string,string>={ACTIVE:"生效中",INACTIVE:"已停用",DRAFT:"草稿",PUBLISHED:"已上架",RETIRED:"已归档",PENDING_PAYMENT:"待支付",PAYMENT_PROCESSING:"支付确认中",PAID:"支付成功",FULFILLING:"权益到账中",FULFILLED:"已到账",CLOSED:"已关闭",REFUNDING:"退款处理中",REFUNDED:"已退款",EXCEPTION:"到账异常",OPEN:"待处理",RESOLVED:"已解决",PENDING:"待审核",APPROVED:"已通过",REJECTED:"已驳回",EXECUTED:"已完成",FAILED:"执行失败",SEED_ADJUSTMENT:"智慧种子调整",ENTITLEMENT_ADJUSTMENT:"服务权益调整",RECONCILIATION_RESOLVE:"完成对账处理",PRODUCT_CHANGE:"商品配置变更",ACCOUNT_CREATED:"创建运营账号",ACCOUNT_ROLES_UPDATED:"更新账号权限",ACCOUNT_PASSWORD_RESET:"重置账号密码",ACCOUNT_DELETED:"删除运营账号",PRODUCT_REVIEW_SUBMITTED:"提交商品审核",PRODUCT_VERSION_PUBLISHED:"发布商品版本",ACTION_REQUEST_REJECTED:"驳回审核申请",DAILY_ENERGY:"今日能量",CARD_READING:"抽卡问事",RELATIONSHIP_READING:"关系疗愈",MEMBERSHIP:"会员权益",OFFLINE_SERVICE:"线下服务"};
