const cn=(value:unknown)=>statusCn[String(value)]||String(value||"—");
const specForEditor=(value:Record<string,unknown>)=>Array.isArray(value?.benefits)?Object.fromEntries(value.benefits.map(item=>{const benefit=item as Record<string,unknown>,key=benefit.serviceType==="DAILY_INSIGHT"?"DAILY_ENERGY":String(benefit.serviceType);return [key,Number(benefit.quantity)||1]})):Object.fromEntries(Object.entries(value||{}).filter(([key])=>key!=="periodDays"&&key!=="benefits").map(([key,quantity])=>[key,Number(quantity)||1]));
const userFromApi=(x:any):User=>{const phone=x.phone_masked||"未绑定手机号",code=`FRESH-${String(x.id).replaceAll('-','').slice(-6).toUpperCase()}`,name=x.nickname||"未设置昵称";return {id:x.id,code,phone,name,profile:"查看详情",member:"查看权益",seed:Number(x.seed_balance||0),status:cn(x.status)}};
const UserLabel=({user}:{user?:UserIdentity|null})=><span className="user-identity"><b>{user?.nickname||"未设置昵称"}</b><small>{user?.phone_masked||"未绑定手机号"}</small></span>;

export default function AdminPage(){
 const [view,setView]=useState<View>("dashboard"),[user,setUser]=useState<User|null>(null),[toast,setToast]=useState("");
 const [auth,setAuth]=useState<"checking"|"ready"|"login">("checking"),[liveUsers,setLiveUsers]=useState<User[]>([]),[liveGoods,setLiveGoods]=useState<Product[]>([]),[liveOrders,setLiveOrders]=useState<Order[]>([]),[dashboard,setDashboard]=useState<DashboardData|null>(null),[operator,setOperator]=useState<CurrentOperator|null>(null),[loadError,setLoadError]=useState("");
 const load=async()=>{setLoadError("");try{const [u,p,o,d,m]=await Promise.all([operationsFetch<{data:any[]}>("/users"),operationsFetch<{data:any[]}>("/products"),operationsFetch<{data:any[]}>("/orders?page=1&pageSize=20"),operationsFetch<{data:DashboardData}>("/dashboard"),operationsFetch<{data:CurrentOperator}>("/me")]);setLiveUsers(u.data.map(userFromApi));setLiveGoods(p.data.map(x=>{const draft=x.draft_payload||{},rawSpec=draft.entitlementSpec||x.entitlement_spec||{},spec=specForEditor(rawSpec),offeringStatus=draft.offeringStatus||x.offering_status||"DRAFT",promotion=draft.promotion||{enabled:Boolean(x.reserved_seed_quantity),minimumSeedBalance:Number(x.minimum_seed_balance||0),reservedSeedQuantity:Number(x.reserved_seed_quantity||1),activityAmountMinor:Number(x.activity_amount_minor||0)},amountMinor=Number(draft.amountMinor??x.amount_minor??0),validityDays=draft.validityDays??x.validity_days??null;return {id:x.code||x.id,offeringId:x.id,serviceType:x.service_type,name:draft.displayName||x.display_name||"未命名商品",kind:x.offering_kind==="MEMBERSHIP"?"会员计划":x.offering_kind==="PACKAGE"?"服务包":"单次产品",price:`¥ ${(amountMinor/100).toFixed(2)}`,amountMinor,seedPrice:promotion.enabled?`${promotion.minimumSeedBalance||0} 颗解锁 ¥ ${(Number(promotion.activityAmountMinor||0)/100).toFixed(2)}`:"未配置",version:`V${x.version||1}`,status:x.pending_request_status==="PENDING"?"待审核":x.pending_request_status==="FAILED"?"审核执行失败":productStatusCn[offeringStatus]||offeringStatus,offeringStatus,summary:draft.description||x.description||"暂无用户端说明",validity:validityDays?`购买后 ${validityDays} 天`:"长期有效",validityDays,delivery:"购买成功后生效",contents:Object.entries(spec).map(([k,v])=>`${cn(k)} × ${v}`),entitlementSpec:spec,promotion,draft:x.draft_payload,pendingRequestId:x.pending_request_id}}));setLiveOrders(o.data.map(x=>({id:x.order_number||x.id,user:x.user,item:x.display_name||"未命名商品",amount:`¥ ${(Number(x.amount_minor||0)/100).toFixed(2)}`,pay:cn(x.status),grant:cn(x.fulfillment_status)})));setDashboard(d.data);setOperator(m.data);setAuth("ready")}catch(e){if(String(e).includes("登录")||String(e).includes("401")){localStorage.removeItem("fresh_operations_token");setAuth("login")}else{setLoadError(e instanceof Error?e.message:"数据加载失败");setAuth("ready")}}};
 useEffect(()=>{if(localStorage.getItem("fresh_operations_token"))void load();else setAuth("login")},[]);
 if(auth==="checking")return <main className="operations-login"><p>正在验证运营账号…</p></main>;
 if(auth==="login")return <OperationsLogin done={()=>{setAuth("checking");void load()}}/>;
 const go=(v:View)=>{setView(v);setUser(null)}; const tell=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(""),2200)};const logout=()=>{localStorage.removeItem("fresh_operations_token");setOperator(null);setAuth("login")};
 const title={dashboard:"工作台",users:"用户中心",benefits:"权益中心",products:"商品中心",orders:"交易中心",approvals:"审核中心",system:"系统管理",audit:"操作审计"}[view];
 return <main className="admin-shell">
  <aside className="admin-sidebar"><div className="admin-brand"><span className="admin-brand-mark">初</span><div><strong>初见 · FRESH</strong><small>运营管理平台</small></div></div><nav>{nav.map(([id,label,icon])=><button className={view===id?"is-active":""} onClick={()=>go(id)} key={id}><i>{icon}</i><span>{label}</span></button>)}</nav><div className="admin-account"><span>{operator?.nickname?.slice(0,1)||"管"}</span><div><strong>{operator?.nickname||"运营账号"}</strong><small>{operator?.roles?.map(x=>x.name).join(" · ")||"已授权"}</small></div></div></aside>
  <section className="admin-main"><header className="admin-topbar"><div><p>{({dashboard:"ADMIN-HOME-01",users:"ADMIN-USER-01",benefits:"ADMIN-BENEFIT-01",products:"ADMIN-PRODUCT-01",orders:"ADMIN-ORDER-01",approvals:"ADMIN-APPROVAL-01",system:"ADMIN-SYSTEM-01",audit:"ADMIN-AUDIT-01"})[view]}</p><h1>{title}</h1></div><div className="admin-top-actions">{operator?.roles?.some(x=>x.code==="SUPER_ADMIN")&&<button className="admin-secondary" onClick={()=>go("system")}>账号与权限</button>}<button className="admin-secondary" onClick={()=>go("audit")}>操作记录</button><button className="admin-secondary session-action" onClick={logout}>退出登录</button></div></header>
   {loadError&&<div className="risk-note">真实数据加载失败：{loadError} <button onClick={()=>void load()}>重试</button></div>}
   {view==="dashboard"&&<Dashboard go={go} data={dashboard}/>} {view==="users"&&<Users data={liveUsers} reload={load} open={setUser}/>} {view==="benefits"&&<Benefits tell={tell}/>} {view==="products"&&<Products data={liveGoods} tell={tell} reload={load}/>} {view==="orders"&&<Orders data={liveOrders} tell={tell}/>} {view==="approvals"&&<Approvals tell={tell}/>} {view==="system"&&<System tell={tell} operator={operator}/>} {view==="audit"&&<Audit/>}
  </section>
  {user&&<UserPanelLive user={user} close={()=>setUser(null)}/>} {toast&&<div className="admin-toast">✓ {toast}</div>}
 </main>
}

function Dashboard({go,data}:{go:(v:View)=>void;data:DashboardData|null}){const stats=[["用户总数",String(data?.total_users??"—"),"平台注册用户"],["累计营收",data?`¥ ${(Number(data.revenue_minor||0)/100).toLocaleString("zh-CN",{minimumFractionDigits:2})}`:"—","已支付且有效订单"],["今日新增用户",String(data?.new_users??"—"),"来自 R1.1 用户数据"],["待处理对账",String(data?.open_cases??"—"),"需要运营核对"],["严重到账异常",String(data?.critical_cases??"—"),"优先处理"],["待支付订单",String(data?.pending_orders??"—"),"来自真实订单"]];return <><section className="admin-stat-grid dashboard-kpis">{stats.map(s=><article className="admin-stat" key={s[0]}><p>{s[0]}</p><strong>{s[1]}</strong><small>{s[2]}</small></article>)}</section><section className="admin-grid"><article className="admin-panel"><Head en="TODAY" title="今日待处理"/><Task tone="danger" title={`${data?.critical_cases??0} 笔严重到账异常`} note="优先核对支付回调与权益发放流水" action="立即处理" click={()=>go("orders")}/><Task tone="warning" title={`${data?.open_cases??0} 条对账事项待处理`} note="处理结果将写入操作审计" action="查看事项" click={()=>go("benefits")}/><Task tone="info" title="商品配置按版本管理" note="修改先保存草稿，经审核后发布" action="商品中心" click={()=>go("products")}/></article><article className="admin-panel"><Head en="QUICK ACCESS" title="常用操作"/><div className="admin-quick-grid"><button onClick={()=>go("users")}><b>查</b><span>查询用户</span></button><button onClick={()=>go("benefits")}><b>赠</b><span>权益流水</span></button><button onClick={()=>go("products")}><b>品</b><span>配置产品</span></button><button onClick={()=>go("orders")}><b>单</b><span>诊断订单</span></button></div></article></section></>}
function Users({data,reload,open}:{data:User[];reload:()=>Promise<void>;open:(u:User)=>void}){const [query,setQuery]=useState(""),[result,setResult]=useState<User[]>(data),[loading,setLoading]=useState(false);useEffect(()=>setResult(data),[data]);const search=async()=>{setLoading(true);try{const response=await operationsFetch<{data:any[]}>(`/users?q=${encodeURIComponent(query)}`);setResult(response.data.map(userFromApi))}finally{setLoading(false)}};return <section className="admin-page"><div className="admin-toolbar"><label className="admin-search">⌕<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="输入手机号或账户编号" onKeyDown={e=>e.key==="Enter"&&void search()}/></label><button className="admin-primary" onClick={()=>void search()} disabled={loading}>{loading?"查询中…":"查询用户"}</button><button className="admin-secondary" onClick={()=>{setQuery("");void reload()}}>重置</button><span className="admin-hint">手机号默认脱敏展示，完整手机号仅用于精确查询。</span></div><article className="admin-panel admin-table-panel"><Head en="USER LIST" title={`用户列表 · ${result.length} 人`}/>{result.length?<><table><thead><tr><th>用户</th><th>账户编码</th><th>档案</th><th>会员</th><th>智慧种子</th><th>状态</th><th/></tr></thead><tbody>{result.map(u=><tr key={u.id||u.phone}><td><b>{u.name}</b><small>{u.phone}</small></td><td><b>{u.code}</b></td><td>{u.profile}</td><td>{u.member}</td><td>{u.seed} 颗</td><td><Tag value={u.status}/></td><td><button className="admin-link" onClick={()=>open(u)}>查看详情 →</button></td></tr>)}</tbody></table><Pagination/></>:<div className="empty-state"><b>没有找到匹配用户</b><span>请检查手机号或账户编号。</span></div>}</article></section>}
function Benefits({tell:_tell}:{tell:(s:string)=>void}){const [tab,setTab]=useState("智慧种子"),[data,setData]=useState<any[]>([]),[error,setError]=useState("");const tabs=["智慧种子","服务权益","待领取权益"];useEffect(()=>{operationsFetch<{data:any[]}>("/benefits").then(x=>setData(x.data)).catch(e=>setError(e.message))},[]);const filtered=data.filter(x=>tab==="待领取权益"?x.status==="PENDING_CLAIM":x.kind===tab);return <section className="admin-page"><div className="admin-tabbar">{tabs.map(x=><button className={tab===x?"is-active":""} onClick={()=>setTab(x)} key={x}>{x}<b>{x==="待领取权益"?data.filter(y=>y.status==="PENDING_CLAIM").length:data.filter(y=>y.kind===x).length}</b></button>)}</div>{error&&<div className="risk-note">{error}</div>}<article className="admin-panel admin-table-panel"><Head en="BENEFIT LEDGER" title={`${tab} · 权益明细`}/>{filtered.length?<table><thead><tr><th>记录编号</th><th>用户</th><th>总量</th><th>可用</th><th>到期时间</th><th>状态</th></tr></thead><tbody>{filtered.map(x=><tr key={x.id}><td><b>{String(x.id).slice(0,8)}</b></td><td><UserLabel user={x.user}/></td><td>{x.total_quantity}</td><td>{x.available_quantity}</td><td>{x.expires_at?new Date(x.expires_at).toLocaleDateString("zh-CN"):"长期"}</td><td><Tag value={cn(x.status)}/></td></tr>)}</tbody></table>:<div className="empty-state"><b>暂无记录</b><span>这里不会使用示例数据填充。</span></div>}</article></section>}
function SeedLedger(){return <><section className="admin-stat-grid compact"><Stat a="今日发放" b="1,280" c="42 位用户"/><Stat a="今日使用" b="386" c="含 27 笔预占"/><Stat a="异常流水" b="2" c="等待人工复核"/></section><article className="admin-panel admin-table-panel"><Head en="SEED LEDGER" title="最近智慧种子流水"/><table><thead><tr><th>时间</th><th>用户</th><th>变化</th><th>余额</th><th>来源</th><th>业务单据</th><th>结果</th></tr></thead><tbody><tr><td>10:31</td><td>林知夏</td><td className="positive">+18</td><td>18</td><td>新用户启程礼</td><td>GR20260902031</td><td><Tag value="已到账"/></td></tr><tr><td>10:18</td><td>许遥</td><td>-80</td><td>80</td><td>清和计划解锁价</td><td>FR202609020017</td><td><Tag value="已预占"/></td></tr><tr><td>09:46</td><td>周予安</td><td className="positive">+18</td><td>0</td><td>客服异常补偿</td><td>GR20260902024</td><td><Tag value="待领取"/></td></tr></tbody></table><Pagination/></article></>}
