function ProductPreview({product}:{product:Product}){return <div className="preview-stage"><div className="preview-phone"><p className="preview-brand">初见 · FRESH</p><small>{product.kind}</small><h3>{product.name}</h3><p>{product.summary}</p><div className="preview-price"><b>{product.price}</b><span>{product.seedPrice}</span></div><ul>{product.contents.map(x=><li key={x}>✓ {x}</li>)}</ul><div className="preview-note">有效期：{product.validity}<br/>权益将在{product.delivery}</div><button>确认购买</button></div><aside><p className="admin-eyebrow">PREVIEW CHECK</p><h3>发布前预览</h3><ul><li>名称与说明是否面向用户表达</li><li>价格和种子条件是否清晰</li><li>权益次数与有效期是否一致</li><li>不展示内部版本号与状态枚举</li></ul></aside></div>}
function Delivery({product}:{product:Product}){return <><div className="config-card"><b>交付内容</b><p>{product.contents[0]}</p><span>完成支付或权益核销后即时发放</span></div><div className="form-grid"><Field label="使用次数" value="1 次"/><Field label="核销方式" value="用户发起服务时自动核销"/><Field label="失败处理" value="权益不扣减，可安全重试"/><Field label="记录保留" value="长期保留在用户问事记录"/></div></>}
function Bundle({product}:{product:Product}){return <><div className="bundle-list">{product.contents.map((x,i)=><div key={x}><span>{i+1}</span><b>{x}</b><label>发放方式<select defaultValue={i===0?"一次性发放":"随会员生效"}><option>一次性发放</option><option>随会员生效</option><option>每周期刷新</option></select></label><button>移除</button></div>)}</div><button className="admin-secondary">＋ 添加单次产品或服务包</button><div className="risk-note">组合发布后会生成权益快照。组成项未来修改，不会反向影响已购买用户。</div></>}
function Pricing({product}:{product:Product}){return <><div className="form-grid"><Field label="标准售价" value={product.price.replace("¥ ","")} suffix="元"/><Field label="会员专属价" value={product.kind==="会员计划"?"不适用":"5.90"} suffix="元"/><Field label="活动价格" value="未启用"/><Field label="价格生效时间" value="发布后立即生效"/></div><h4>智慧种子解锁价格</h4><div className="seed-rule"><label><input type="checkbox" defaultChecked/> 启用智慧种子解锁价</label><Field label="所需智慧种子" value={product.kind==="会员计划"?"160":"80"} suffix="颗"/><Field label="解锁后价格" value={product.kind==="会员计划"?"179.00":"49.90"} suffix="元"/><Field label="种子处理方式" value="支付前预占，成功后扣除"/></div><div className="quote-example"><b>报价模拟</b><span>普通用户：{product.price}</span><span>满足种子条件：{product.seedPrice}</span><button>更换模拟用户</button></div></>}
function Versions({product}:{product:Product}){return <div className="version-list"><div><Tag value={product.status}/><b>{product.version} · 当前版本</b><span>Fred · 今天 10:18</span><button>查看差异</button></div><div><Tag value="已归档"/><b>V2 · 上一个版本</b><span>jiucongtian · 8 月 30 日 18:42</span><button>查看快照</button></div><div><Tag value="已归档"/><b>V1 · 首次发布</b><span>Fred · 8 月 26 日 11:05</span><button>查看快照</button></div></div>}
function NewProduct({close,created}:{close:()=>void;created:()=>Promise<void>}){const [kind,setKind]=useState<"SINGLE"|"PACKAGE"|"MEMBERSHIP">("SINGLE"),[code,setCode]=useState(""),[name,setName]=useState(""),[serviceType,setServiceType]=useState("CARD_READING"),[busy,setBusy]=useState(false),[error,setError]=useState("");const effectiveService=kind==="MEMBERSHIP"?"MEMBERSHIP":serviceType,initialSpec=kind==="MEMBERSHIP"?{}:{[effectiveService]:1};const submit=async()=>{setBusy(true);setError("");try{await operationsFetch("/products",{method:"POST",body:JSON.stringify({code:code.trim().toLowerCase(),serviceType:effectiveService,offeringKind:kind,displayName:name.trim(),description:`${name.trim()}的用户端说明`,amountMinor:0,validityDays:null,offeringStatus:"DRAFT",entitlementSpec:initialSpec,promotion:{enabled:false,minimumSeedBalance:0,reservedSeedQuantity:1,activityAmountMinor:0}})});await created()}catch(e){setError(e instanceof Error?e.message:"创建失败")}finally{setBusy(false)}};return <div className="admin-overlay"><section className="admin-modal account-modal"><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">NEW PRODUCT</p><h2>创建商品草稿</h2><label>商品类型<select value={kind} onChange={e=>setKind(e.target.value as typeof kind)}><option value="SINGLE">单次产品</option><option value="PACKAGE">服务包</option><option value="MEMBERSHIP">会员计划</option></select></label><label>商品编号<input value={code} onChange={e=>setCode(e.target.value.replace(/[^a-zA-Z0-9-_]/g,""))} placeholder="例如：card-reading-10"/></label><label>用户端名称<input value={name} onChange={e=>setName(e.target.value)} placeholder="请输入用户能理解的名称"/></label>{kind==="MEMBERSHIP"?<div className="success-note">会员计划可以在下一步组合今日能量、抽卡问事、关系疗愈和线下服务等多项权益，不限制为一种服务。</div>:<label>主要服务类型<select value={serviceType} onChange={e=>setServiceType(e.target.value)}><option value="CARD_READING">抽卡问事</option><option value="DAILY_ENERGY">今日能量</option><option value="RELATIONSHIP_READING">关系疗愈</option><option value="OFFLINE_SERVICE">线下服务</option></select></label>}{error&&<div className="risk-note">{error}</div>}<div className="modal-actions"><button className="admin-secondary" onClick={close}>取消</button><button className="admin-primary" disabled={busy||code.length<3||name.trim().length<2} onClick={()=>void submit()}>{busy?"创建中…":"创建并继续配置"}</button></div></section></div>}
function Field({label,value,disabled,suffix}:{label:string;value:string;disabled?:boolean;suffix?:string}){return <label className="config-field">{label}<span><input defaultValue={value} disabled={disabled}/>{suffix&&<i>{suffix}</i>}</span></label>}
function Orders({data,tell}:{data:Order[];tell:(s:string)=>void}){const [rows,setRows]=useState(data),[status,setStatus]=useState(""),[query,setQuery]=useState(""),[appliedQuery,setAppliedQuery]=useState(""),[page,setPage]=useState(1),[total,setTotal]=useState(0),[totalPages,setTotalPages]=useState(1),[loading,setLoading]=useState(false),[selected,setSelected]=useState<Order|null>(null);useEffect(()=>{let active=true;setLoading(true);operationsFetch<{data:any[];pagination:{total:number;totalPages:number}}>(`/orders?page=${page}&pageSize=20&status=${encodeURIComponent(status)}&q=${encodeURIComponent(appliedQuery)}`).then(x=>{if(!active)return;setRows(x.data.map(o=>({id:o.order_number||o.id,user:o.user,item:o.display_name||"未命名商品",amount:`¥ ${(Number(o.amount_minor||0)/100).toFixed(2)}`,pay:cn(o.status),grant:cn(o.fulfillment_status)})));setTotal(x.pagination.total);setTotalPages(x.pagination.totalPages)}).catch(e=>tell(e instanceof Error?e.message:"订单加载失败")).finally(()=>active&&setLoading(false));return()=>{active=false}},[page,status,appliedQuery]);const search=()=>{setPage(1);setAppliedQuery(query.trim())};return <section className="admin-page"><div className="admin-toolbar"><label className="admin-search">⌕<input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==="Enter"&&search()} placeholder="输入订单号、脱敏手机号或请求编号"/></label><button className="admin-primary" onClick={search} disabled={loading}>{loading?"查询中…":"查询订单"}</button><select value={status} onChange={e=>{setPage(1);setStatus(e.target.value)}}><option value="">全部状态</option><option value="PENDING_PAYMENT">待支付</option><option value="PAYMENT_PROCESSING">支付确认中</option><option value="FULFILLED">已到账</option><option value="EXCEPTION">到账异常</option><option value="REFUNDED">已退款</option></select></div><article className="admin-panel admin-table-panel"><Head en="ORDER & DELIVERY" title={`订单与权益到账 · 共 ${total} 笔`}/>{rows.length?<><table><thead><tr><th>订单</th><th>用户</th><th>商品</th><th>金额</th><th>支付</th><th>权益</th><th/></tr></thead><tbody>{rows.map(o=><tr key={o.id}><td><b>{o.id}</b></td><td><UserLabel user={o.user}/></td><td>{o.item}</td><td>{o.amount}</td><td>{o.pay}</td><td><Tag value={o.grant}/></td><td><button className="admin-link" onClick={()=>setSelected(o)}>诊断 →</button></td></tr>)}</tbody></table><Pagination page={page} total={total} pageSize={20} totalPages={totalPages} change={setPage}/></>:<div className="empty-state"><b>{loading?"正在加载订单":"暂无匹配订单"}</b><span>可调整查询条件后重试。</span></div>}</article>{selected&&<OrderDiagnostic order={selected} close={()=>setSelected(null)} tell={tell}/>}</section>}
