function UserPanel({user,close,grant}:{user:User;close:()=>void;grant:()=>void}){const [tab,setTab]=useState("概览");return <div className="admin-overlay" onClick={close}><aside className="admin-drawer user-drawer" onClick={e=>e.stopPropagation()}><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">USER PROFILE · ADMIN-USER-02</p><h2>{user.name}</h2><p className="drawer-phone">{user.phone} · 用户编号 U20260828031</p><div className="drawer-summary"><Info a="档案状态" b={user.profile}/><Info a="智慧种子" b={`${user.seed} 颗`}/><Info a="会员计划" b={user.member}/><Info a="账号状态" b={user.status}/></div><div className="mini-tabs">{["概览","权益","订单","服务记录","客服记录"].map(x=><button className={tab===x?"is-active":""} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div>{tab==="概览"&&<><h3>最近状态</h3><ul className="timeline"><li><b>今日能量生成成功</b><span>今天 08:12</span></li><li><b>会员权益完成刷新</b><span>9 月 1 日 00:03</span></li><li><b>完成生命智慧档案</b><span>8 月 28 日 19:45</span></li></ul></>}{tab==="权益"&&<DetailList items={[["智慧种子",`${user.seed} 颗 · 正常`],["会员",`${user.member} · 2026-10-01 到期`],["服务包","抽卡问事 8/10 次"]]}/>} {tab==="订单"&&<DetailList items={[["FR202609020018","清和计划 · ¥199.00 · 支付成功"],["FR202608280075","抽卡问事 · 1 次权益 · 已完成"]]}/>} {tab==="服务记录"&&<DetailList items={[["今日能量","今天 08:12 · 生成成功"],["抽卡问事","9 月 1 日 21:42 · 报告已完成"]]}/>} {tab==="客服记录"&&<DetailList items={[["权益不到账咨询","9 月 1 日 · 已解决"],["注册启程礼补发","8 月 28 日 · 操作人 Fred"]]}/>}<button className="admin-primary full" onClick={grant}>为该用户发放权益</button></aside></div>}
function UserPanelLive({user,close}:{user:User;close:()=>void}){const [detail,setDetail]=useState<any|null>(null),[error,setError]=useState("");useEffect(()=>{if(user.id)operationsFetch<{data:any}>(`/users/${user.id}`).then(x=>setDetail(x.data)).catch(e=>setError(e.message))},[user.id]);const items=(detail?.entitlements||[]).map((x:any)=>[`${cn(x.service_type)} · ${String(x.id).slice(0,8)}`,`${x.available_quantity}/${x.total_quantity} · ${cn(x.status)}`]);const seedItems=(detail?.seeds||[]).map((x:any)=>[`智慧种子 · ${String(x.id).slice(0,8)}`,`${x.available_quantity}/${x.total_quantity} · ${cn(x.status)}`]);const orderItems=(detail?.orders||[]).map((x:any)=>[x.order_number||String(x.id).slice(0,8),`¥ ${(Number(x.amount_minor||0)/100).toFixed(2)} · ${cn(x.status)}`]);return <div className="admin-overlay" onClick={close}><aside className="admin-drawer user-drawer" onClick={e=>e.stopPropagation()}><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">USER PROFILE · ADMIN-USER-02</p><h2>{user.name}</h2><p className="drawer-phone">账户编号 {user.code}</p><details className="technical-id"><summary>技术排查信息</summary><code>{user.id}</code></details><div className="drawer-summary"><Info a="账号状态" b={user.status}/><Info a="智慧种子" b={`${user.seed} 颗`}/><Info a="订单数" b={detail?String(detail.orders?.length||0):"加载中"}/><Info a="服务权益" b={detail?String(detail.entitlements?.length||0):"加载中"}/></div>{error&&<div className="risk-note">{error}</div>}<h3>智慧种子与服务权益</h3><DetailList items={[...seedItems,...items]}/><h3>订单记录</h3><DetailList items={orderItems}/></aside></div>}
function DetailList({items}:{items:string[][]}){return <div className="detail-list">{items.length?items.map((x,i)=><div key={`${x[0]}-${i}`}><b>{x[0]}</b><span>{x[1]}</span></div>):<p className="empty-detail">暂无记录</p>}</div>}
function Grant({close,done}:{close:()=>void;done:()=>void}){const [kind,setKind]=useState("智慧种子"),[phone,setPhone]=useState("13113011314");const unregistered=phone==="13900002016";return <div className="admin-overlay"><section className="admin-modal grant-modal"><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">MANUAL GRANT · ADMIN-BENEFIT-05</p><h2>人工发放</h2><label>用户手机号<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="输入完整手机号"/></label><label>发放类型<select value={kind} onChange={e=>setKind(e.target.value)}><option>智慧种子</option><option>会员计划</option><option>服务包</option><option>单次产品</option></select></label>{kind==="智慧种子"&&<div className="form-row"><label>发放数量<input defaultValue="18"/><small>单位：颗</small></label><label>有效期<select><option>长期有效</option><option>30 天</option><option>90 天</option></select></label></div>}{kind==="会员计划"&&<><label>会员计划<select><option>清和计划 V4</option><option>微光计划 V2</option><option>自在计划 V1</option></select></label><div className="form-row"><label>期限<select><option>固定 30 天</option><option>90 天</option><option>180 天</option></select></label><label>生效方式<select><option>立即生效</option><option>首次登录后生效</option><option>指定日期生效</option></select></label></div></>}{kind==="服务包"&&<><label>服务包<select><option>抽卡问事 · 10 次包 V2</option><option>关系疗愈 · 3 次包 V1</option></select></label><div className="form-row"><label>数量<input defaultValue="1"/><small>单位：份</small></label><label>有效期<select><option>购买规则：180 天</option><option>指定日期</option></select></label></div></>}{kind==="单次产品"&&<><label>单次产品<select><option>抽卡问事 V3</option><option>今日能量指引 V2</option></select></label><div className="form-row"><label>次数<input defaultValue="1"/></label><label>核销方式<select><option>用户发起时自动核销</option><option>人工核销</option></select></label></div></>}<label>发放原因<textarea defaultValue="新用户启程礼未正常到账，人工补发。"/></label>{unregistered?<div className="risk-note">该手机号尚未注册。本次权益将进入“待领取权益”，用户通过该手机号注册或登录后自动领取。</div>:<div className="success-note">已找到用户：林知夏。提交后将生成权益流水和操作审计记录。</div>}<label className="confirm-check"><input type="checkbox" defaultChecked/> 我已核对用户、发放内容、数量和有效期</label><div className="modal-actions"><button className="admin-secondary" onClick={close}>保存草稿</button><button className="admin-primary" onClick={done}>{kind==="智慧种子"?"提交审核":"确认并提交审核"}</button></div></section></div>}
function Approvals({tell}:{tell:(s:string)=>void}){const [data,setData]=useState<any[]>([]),[busy,setBusy]=useState("");const load=()=>operationsFetch<{data:any[]}>("/action-requests").then(x=>setData(x.data));useEffect(()=>{void load()},[]);const review=async(id:string,decision:"approve"|"reject")=>{setBusy(id);try{await operationsFetch(`/action-requests/${id}/${decision}`,{method:"POST",body:JSON.stringify({note:decision==="approve"?"核对无误，同意执行":"资料不足，暂不执行"})});tell(decision==="approve"?"审核通过并已执行":"申请已驳回");await load()}catch(e){tell(e instanceof Error?e.message:"审核失败")}finally{setBusy("")}};const kind=(value:string)=>({SINGLE:"单次产品",PACKAGE:"服务包",MEMBERSHIP:"会员计划"})[value]||"商品";return <section className="admin-page"><div className="success-note">普通账号遵循创建与审批分离；超级管理员可在人员不足时审批自己的申请，所有操作都会写入审计记录。执行失败的申请可修复原因后重试。</div><article className="admin-panel admin-table-panel"><Head en="APPROVAL CENTER" title={`审核申请 · ${data.length}`}/>{data.length?<table><thead><tr><th>申请内容</th><th>修改内容</th><th>申请原因</th><th>提交人</th><th>提交时间</th><th>状态</th><th/></tr></thead><tbody>{data.map(x=><tr key={x.id}><td><b>{x.action_type==="PRODUCT_CHANGE"?(x.payload?.displayName||x.payload?.code||"未命名商品"):cn(x.action_type)}</b><small>{x.action_type==="PRODUCT_CHANGE"?`${x.payload?.code||"—"} · ${kind(x.payload?.offeringKind)}`:String(x.id).slice(0,8)}</small></td><td><span className="change-list">{Array.isArray(x.payload?.changes)?x.payload.changes.map((change:string)=><small key={change}>• {change}</small>):<small>历史申请未记录差异</small>}</span></td><td>{x.reason}</td><td>{x.submitted_by}</td><td>{new Date(x.created_at).toLocaleString("zh-CN")}</td><td><Tag value={cn(x.status)}/></td><td>{["PENDING","FAILED"].includes(x.status)&&<><button disabled={busy===x.id} className="admin-link" onClick={()=>void review(x.id,"approve")}>{x.status==="FAILED"?"重新执行":"通过并执行"}</button> <button disabled={busy===x.id} className="admin-link" onClick={()=>void review(x.id,"reject")}>驳回</button></>}</td></tr>)}</tbody></table>:<div className="empty-state"><b>暂无审核申请</b><span>人工权益调整和商品变更会在这里留下审批记录。</span></div>}</article></section>}
function System({tell,operator}:{tell:(s:string)=>void;operator:CurrentOperator|null}){const superAdmin=Boolean(operator?.roles?.some(x=>x.code==="SUPER_ADMIN")),tabs=superAdmin?["账号与角色","权限矩阵","我的资料"]:["我的资料"], [tab,setTab]=useState(tabs[0]);return <section className="admin-page"><div className="admin-tabbar">{tabs.map(x=><button className={tab===x?"is-active":""} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div>{tab==="账号与角色"&&<AccountManager tell={tell}/>} {tab==="权限矩阵"&&<PermissionMatrix/>} {tab==="我的资料"&&<MyProfile operator={operator} tell={tell}/>}</section>}
function AccountManager({tell}:{tell:(s:string)=>void}){const [accounts,setAccounts]=useState<OperationAccount[]>([]),[roles,setRoles]=useState<OperationRole[]>([]),[editing,setEditing]=useState<OperationAccount|null|"new">(null),[initialPassword,setInitialPassword]=useState("");const load=async()=>{const [a,r]=await Promise.all([operationsFetch<{data:OperationAccount[]}>("/accounts"),operationsFetch<{data:OperationRole[]}>("/meta/operation-roles")]);setAccounts(a.data);setRoles(r.data)};useEffect(()=>{void load()},[]);const reset=async(a:OperationAccount)=>{if(!window.confirm(`确认重置“${a.nickname}”的登录密码？旧密码将立即失效。`))return;try{const result=await operationsFetch<{data:{initialPassword:string}}>(`/accounts/${a.id}/reset-password`,{method:"POST"});setEditing(a);setInitialPassword(result.data.initialPassword);await load()}catch(e){tell(e instanceof Error?e.message:"密码重置失败")}};const remove=async(a:OperationAccount)=>{if(!window.confirm(`确认删除运营账号“${a.nickname}（${a.phone}）”？删除后不可登录。`))return;try{await operationsFetch(`/accounts/${a.id}`,{method:"DELETE"});tell("运营账号已删除");await load()}catch(e){tell(e instanceof Error?e.message:"账号删除失败")}};return <><article className="admin-panel admin-table-panel"><div className="panel-title-action"><Head en="ACCOUNT & ROLE" title={`后台账号与角色 · ${accounts.length}`}/><button className="admin-primary" onClick={()=>{setInitialPassword("");setEditing("new")}}>＋ 创建运营账号</button></div><div className="success-note">手机号是运营账号的唯一登录标识，创建后不可修改。超级管理员可配置角色、停用、重置密码或删除普通运营账号。</div><table><thead><tr><th>账号</th><th>已分配角色</th><th>创建时间</th><th>密码状态</th><th>状态</th><th>管理</th></tr></thead><tbody>{accounts.map(a=><tr key={a.id}><td><b>{a.nickname}</b><small>{a.phone}</small></td><td>{a.roles.map(r=><span className="role-chip" key={r.code}>{r.name}</span>)}</td><td>{new Date(a.created_at).toLocaleDateString("zh-CN")}</td><td>{a.password_changed_at?"已自行修改":"使用初始密码"}</td><td><Tag value={a.status==="ACTIVE"?"正常":"已停用"}/></td><td><button className="admin-link" onClick={()=>{setInitialPassword("");setEditing(a)}}>配置</button> <button className="admin-link" onClick={()=>void reset(a)}>重置密码</button> <button className="admin-link danger-link" onClick={()=>void remove(a)}>删除</button></td></tr>)}</tbody></table>{accounts.length===0&&<div className="empty-state"><b>暂无手机号运营账号</b><span>可以创建第一位运营人员。</span></div>}</article>{editing&&<AccountEditor account={editing==="new"?null:editing} roles={roles} initialPassword={initialPassword} close={()=>setEditing(null)} saved={async password=>{setInitialPassword(password||"");if(!password){setEditing(null);tell("账号权限已更新")}await load()}}/>}</>}
function AccountEditor({account,roles,initialPassword,close,saved}:{account:OperationAccount|null;roles:OperationRole[];initialPassword:string;close:()=>void;saved:(password?:string)=>Promise<void>}){const [phone,setPhone]=useState(account?.phone||""),[nickname,setNickname]=useState(account?.nickname||""),[selected,setSelected]=useState<string[]>(account?.roles.map(x=>x.code)||["PRODUCT_OPERATOR"]),[status,setStatus]=useState(account?.status||"ACTIVE"),[busy,setBusy]=useState(false),[error,setError]=useState("");const toggle=(code:string)=>setSelected(x=>x.includes(code)?x.filter(y=>y!==code):[...x,code]);const submit=async()=>{setBusy(true);setError("");try{if(account){await operationsFetch(`/accounts/${account.id}/roles`,{method:"PATCH",body:JSON.stringify({roles:selected,status})});await saved()}else{const result=await operationsFetch<{data:{initialPassword:string}}>("/accounts",{method:"POST",body:JSON.stringify({phone,nickname,roles:selected})});await saved(result.data.initialPassword)}}catch(e){setError(e instanceof Error?e.message:"保存失败")}finally{setBusy(false)}};return <div className="admin-overlay"><section className="admin-modal account-modal"><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">{account?"ACCOUNT MANAGEMENT":"CREATE OPERATOR"}</p><h2>{account?"管理运营账号":"创建运营账号"}</h2>{initialPassword?<div className="initial-password"><b>{account?"密码已重置":"账号创建成功"}</b><p>新初始密码仅展示这一次，请安全交给账号本人。</p><code>{initialPassword}</code><button className="admin-primary full" onClick={close}>我已保存，完成</button></div>:<><label>登录手机号<input value={phone} disabled={Boolean(account)} onChange={e=>setPhone(e.target.value.replace(/\D/g,"").slice(0,11))} placeholder="11 位手机号"/></label><label>昵称<input value={nickname} disabled={Boolean(account)} onChange={e=>setNickname(e.target.value)} placeholder="例如：客服小青"/></label><fieldset className="role-options"><legend>分配角色</legend>{roles.map(role=><label key={role.code}><input type="checkbox" checked={selected.includes(role.code)} onChange={()=>toggle(role.code)}/><span>{role.name}</span></label>)}</fieldset>{account&&<label>账号状态<select value={status} onChange={e=>setStatus(e.target.value)}><option value="ACTIVE">正常</option><option value="DISABLED">停用</option></select></label>}{error&&<div className="risk-note">{error}</div>}<div className="modal-actions"><button className="admin-secondary" onClick={close}>取消</button><button className="admin-primary" disabled={busy||selected.length===0||(!account&&(phone.length!==11||nickname.length<2))} onClick={()=>void submit()}>{busy?"保存中…":account?"保存配置":"创建账号"}</button></div></>}</section></div>}
function MyProfile({operator,tell}:{operator:CurrentOperator|null;tell:(s:string)=>void}){const [nickname,setNickname]=useState(operator?.nickname||""),[currentPassword,setCurrentPassword]=useState(""),[newPassword,setNewPassword]=useState("");if(operator?.bootstrap)return <article className="admin-panel placeholder-panel"><span>系统引导管理员</span><h2>{operator.nickname}</h2><p>该账号由测试服务器安全配置维护。手机号运营账号可在这里自行修改昵称与密码。</p></article>;const save=async()=>{try{await operationsFetch('/me',{method:'PATCH',body:JSON.stringify({nickname,currentPassword:currentPassword||undefined,newPassword:newPassword||undefined})});setCurrentPassword("");setNewPassword("");tell("个人资料已更新")}catch(e){tell(e instanceof Error?e.message:"更新失败")}};return <article className="admin-panel profile-settings"><Head en="MY ACCOUNT" title="我的资料"/><p>登录手机号：<b>{operator?.phone}</b>（唯一标识，不可修改）</p><label>昵称<input value={nickname} onChange={e=>setNickname(e.target.value)}/></label><label>当前密码<input type="password" value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)}/></label><label>新密码<input type="password" value={newPassword} onChange={e=>setNewPassword(e.target.value)} placeholder="至少 8 位；不修改可留空"/></label><button className="admin-primary" onClick={()=>void save()}>保存我的资料</button></article>}
function PermissionMatrix(){const rows=[["超级管理员","读写","读写","读写","读写","正式发布"],["产品运营","只读","读写","只读","只读","提交审核"],["用户运营","读写","只读","读写","只读","—"],["客服","读写","只读","提交申请","只读","—"],["财务","只读","只读","只读","读写","—"],["技术管理员","只读","只读","只读","只读","技术配置"]];return <article className="admin-panel permission-panel"><Head en="RBAC + DATA SCOPE" title="角色权限矩阵"/><div className="permission-grid"><b>角色</b><b>用户</b><b>商品</b><b>权益</b><b>订单</b><b>发布</b>{rows.map(r=><div className="permission-row" key={r[0]}>{r.map((x,i)=>i===0?<strong key={x}>{x}</strong>:<span key={`${r[0]}-${i}`}>{x}</span>)}</div>)}</div><div className="risk-note">一个账号可拥有多个角色，最终权限取有效角色并集。账号本人不能修改自己的权限；正式发布和高风险权益操作仍受审批限制。</div></article>}
function Audit(){const [data,setData]=useState<any[]>([]),[selected,setSelected]=useState<any|null>(null);useEffect(()=>{operationsFetch<{data:any[]}>("/audit").then(x=>setData(x.data)).catch(()=>setData([]))},[]);return <section className="admin-page"><article className="admin-panel admin-table-panel"><Head en="AUDIT LOG" title={`操作审计 · ${data.length}`}/>{data.length?<table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>业务对象</th><th>详情</th></tr></thead><tbody>{data.map(x=><tr key={x.id}><td>{new Date(x.created_at).toLocaleString("zh-CN")}</td><td><UserLabel user={x.actor}/></td><td>{cn(x.action)}</td><td>{cn(x.resource_type)} · {String(x.resource_id||"").slice(0,8)}</td><td><button className="admin-link" onClick={()=>setSelected(x)}>查看记录</button></td></tr>)}</tbody></table>:<div className="empty-state"><b>暂无审计记录</b><span>所有高风险操作都必须可追踪。</span></div>}</article>{selected&&<div className="admin-overlay" onClick={()=>setSelected(null)}><aside className="admin-drawer audit-drawer" onClick={e=>e.stopPropagation()}><button className="admin-close" onClick={()=>setSelected(null)}>×</button><p className="admin-eyebrow">AUDIT DETAIL</p><h2>操作记录详情</h2><div className="drawer-summary"><Info a="操作" b={cn(selected.action)}/><Info a="时间" b={new Date(selected.created_at).toLocaleString("zh-CN")}/><Info a="操作人" b={`${selected.actor?.nickname||"未设置昵称"} · ${selected.actor?.phone_masked||"未绑定手机号"}`}/><Info a="业务对象" b={`${cn(selected.resource_type)} · ${selected.resource_id||"—"}`}/></div><h3>操作内容</h3><pre className="audit-metadata">{JSON.stringify(selected.metadata||{},null,2)}</pre></aside></div>}</section>}
function Pagination({page,total,pageSize,totalPages,change}:{page?:number;total?:number;pageSize?:number;totalPages?:number;change?:(page:number)=>void}){if(!page||total===undefined||!pageSize||!totalPages||!change)return null;const pages=Array.from({length:Math.min(totalPages,5)},(_,i)=>Math.max(1,Math.min(totalPages-4,page-2))+i).filter((x,i,a)=>x>=1&&x<=totalPages&&a.indexOf(x)===i);return <div className="pagination"><span>共 {total} 条 · 每页 {pageSize} 条</span><button disabled={page<=1} onClick={()=>change(page-1)}>上一页</button>{pages.map(x=><button key={x} className={page===x?"is-active":""} onClick={()=>change(x)}>{x}</button>)}<button disabled={page>=totalPages} onClick={()=>change(page+1)}>下一页</button></div>}
function Toolbar({placeholder,button}:{placeholder:string;button:string}){return <div className="admin-toolbar"><label className="admin-search">⌕<input placeholder={placeholder}/></label><button className="admin-primary">{button}</button><span className="admin-hint">默认隐藏敏感信息，完整手机号仅在授权后显示</span></div>}
function Tabs({items}:{items:string[]}){return <div className="admin-tabbar">{items.map((x,i)=><button className={i===0?"is-active":""} key={x}>{x}</button>)}</div>}
function Head({en,title}:{en:string;title:string}){return <div className="admin-panel-head"><div><p className="admin-eyebrow">{en}</p><h2>{title}</h2></div></div>}
function Task({tone,title,note,action,click}:{tone:string;title:string;note:string;action:string;click:()=>void}){return <div className="admin-task"><span className={`admin-dot is-${tone}`}/><div><strong>{title}</strong><p>{note}</p></div><button onClick={click}>{action}</button></div>}
function Stat({a,b,c}:{a:string;b:string;c:string}){return <article className="admin-stat"><p>{a}</p><strong>{b}</strong><small>{c}</small></article>}
function Tag({value}:{value:string}){const cls=/异常/.test(value)?"danger":/待|预占|未发放/.test(value)?"warn":"";return <em className={`tag ${cls}`}>{value}</em>}
function Info({a,b}:{a:string;b:string}){return <div><small>{a}</small><b>{b}</b></div>}
